@@ -0,0 +1,25 @@
+// Sites (kitchens). Every location belongs to one site; a batch is at the
+// site of its location. Items, suppliers, recipes and dishes are shared.
+import { AppError } from "../errors.js";
+
+/** The site of requests that do not name one. */
+export const DEFAULT_SITE = "main";
+
+/** One site (the default one without an id), or AppError unknown_site. */
+export function getSite(store, id = DEFAULT_SITE) {
+  const site = store.data.sites.find((s) => s.id === id);
+  if (!site) throw new AppError("unknown_site", { id });
+  return site;
+}
+
+/** True when the location exists and, if `site` is given, belongs to it. */
+export function hasLocation(store, location, site) {
+  return store.data.locations.some((l) => l.id === location && (site === undefined || l.site === site));
+}
+
+/** A test for batches held at `site`; every batch passes when `site` is undefined. */
+export function atSite(store, site) {
+  if (site === undefined) return () => true;
+  const here = new Set(store.data.locations.filter((l) => l.site === site).map((l) => l.id));
+  return (batch) => here.has(batch.location);
+}
